#!/usr/bin/env python3
"""Run the matched Theme planning matrix as independently supervised JMH cells."""

# Some portions generated by Codex

from __future__ import annotations

import argparse
import hashlib
import json
import pathlib
import subprocess
import sys


THEMES = (
    "MEDICAL_RECORDS",
    "SOCIAL_MEDIA",
    "LIBRARY",
    "ENGINEERING",
    "HIGHLY_CONNECTED",
    "TRAIN",
    "ELECTRICAL_GRID",
    "PHARMA",
    "SPARSE",
)
METHODS = ("planUncachedQuery", "planQuery")
BENCHMARK_CLASS = "org.eclipse.rdf4j.sail.lmdb.benchmark.ThemeQueryPlanRunBenchmark"
COLD_LANE = "cold"
SATURATED_LANE = "saturated"
LANES = (COLD_LANE, SATURATED_LANE)
DEFAULT_WARMUP_ITERATIONS = 10
DEFAULT_WARMUP_SECONDS = 1
DEFAULT_MEASUREMENT_SECONDS = 1


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--jar", type=pathlib.Path, required=True)
    parser.add_argument("--store-root", type=pathlib.Path, required=True)
    parser.add_argument("--results", type=pathlib.Path, required=True)
    parser.add_argument("--timeout-seconds", type=float, default=75.0)
    parser.add_argument("--measurements", type=int, default=7)
    parser.add_argument(
        "--warmup-iterations", type=int, default=DEFAULT_WARMUP_ITERATIONS
    )
    parser.add_argument("--warmup-seconds", type=int, default=DEFAULT_WARMUP_SECONDS)
    parser.add_argument(
        "--measurement-seconds", type=int, default=DEFAULT_MEASUREMENT_SECONDS
    )
    parser.add_argument("--max-cells", type=int)
    parser.add_argument("--resume", action="store_true")
    parser.add_argument("--theme", action="append", choices=THEMES)
    parser.add_argument("--query", action="append", type=int)
    parser.add_argument("--method", action="append", choices=METHODS)
    parser.add_argument("--lane", action="append", choices=LANES)
    args = parser.parse_args()
    if (
        args.timeout_seconds <= 0
        or args.measurements <= 0
        or args.warmup_iterations <= 0
        or args.warmup_seconds <= 0
        or args.measurement_seconds <= 0
    ):
        parser.error("timeout, measurements, warmups, and iteration times must be positive")
    if args.query and any(query < 0 or query > 12 for query in args.query):
        parser.error("query indexes must be in [0,12]")
    return args


def digest(path: pathlib.Path) -> str | None:
    if not path.is_file():
        return None
    value = hashlib.sha256()
    with path.open("rb") as source:
        for block in iter(lambda: source.read(1024 * 1024), b""):
            value.update(block)
    return value.hexdigest()


def jmh_command(
    args: argparse.Namespace,
    method: str,
    theme: str,
    query: int,
    result_path: pathlib.Path,
    lane: str,
) -> list[str]:
    if lane not in LANES:
        raise ValueError(f"unsupported planning timing lane: {lane}")
    benchmark = f"^{BENCHMARK_CLASS}.{method}$"
    jvm_args = (
        "-Xms1G",
        "-Xmx16G",
        "--enable-native-access=ALL-UNNAMED",
        f"-Drdf4j.test.outputDirectory={args.store_root.resolve()}",
        "-Drdf4j.benchmark.profiling=true",
    )
    command = [
        "java",
        "-jar",
        str(args.jar.resolve()),
        benchmark,
        "-p",
        f"themeName={theme}",
        "-p",
        f"z_queryIndex={query}",
        "-f",
        "1",
        "-t",
        "1",
        "-tu",
        "ms",
        "-to",
        "60s",
        "-prof",
        "gc",
        "-rf",
        "json",
        "-rff",
        str(result_path.resolve()),
    ]
    if lane == COLD_LANE:
        command.extend(("-wi", "0", "-i", "1", "-bm", "ss"))
    else:
        command.extend(
            (
                "-wi",
                str(args.warmup_iterations),
                "-w",
                f"{args.warmup_seconds}s",
                "-i",
                str(args.measurements),
                "-r",
                f"{args.measurement_seconds}s",
                "-bm",
                "avgt",
            )
        )
    for argument in jvm_args:
        command.extend(("-jvmArgsAppend", argument))
    return command


def completed(
    status_path: pathlib.Path,
    result_path: pathlib.Path,
    jar: pathlib.Path,
    method: str,
    theme: str,
    query: int,
    measurements: int,
) -> bool:
    if not status_path.is_file() or not result_path.is_file() or result_path.stat().st_size == 0:
        return False
    try:
        status = json.loads(status_path.read_text(encoding="utf-8"))
        result = json.loads(result_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return False
    command = status.get("command")
    if status.get("outcome") != "succeeded" or not isinstance(command, list):
        return False
    try:
        command_jar = pathlib.Path(command[command.index("-jar") + 1])
    except (ValueError, IndexError, TypeError):
        return False
    same_jar = command_jar.resolve() == jar.resolve()
    if not same_jar and digest(command_jar) != digest(jar):
        return False
    if not isinstance(result, list) or len(result) != 1 or not isinstance(result[0], dict):
        return False
    benchmark = result[0]
    params = benchmark.get("params")
    primary = benchmark.get("primaryMetric")
    secondary = benchmark.get("secondaryMetrics")
    allocation = (
        secondary.get("gc.alloc.rate.norm") if isinstance(secondary, dict) else None
    )
    raw = primary.get("rawData") if isinstance(primary, dict) else None
    allocation_raw = allocation.get("rawData") if isinstance(allocation, dict) else None
    return (
        benchmark.get("benchmark") == f"{BENCHMARK_CLASS}.{method}"
        and benchmark.get("mode") == "ss"
        and benchmark.get("threads") == 1
        and benchmark.get("forks") == 1
        and benchmark.get("warmupIterations") == 0
        and benchmark.get("measurementIterations") == measurements
        and isinstance(params, dict)
        and params.get("themeName") == theme
        and params.get("z_queryIndex") == str(query)
        and isinstance(raw, list)
        and len(raw) == 1
        and isinstance(raw[0], list)
        and len(raw[0]) == measurements
        and primary.get("scoreUnit") == "ms/op"
        and isinstance(allocation_raw, list)
        and len(allocation_raw) == 1
        and isinstance(allocation_raw[0], list)
        and len(allocation_raw[0]) == measurements
        and allocation.get("scoreUnit") == "B/op"
    )


def completed_lane(
    status_path: pathlib.Path,
    result_path: pathlib.Path,
    jar: pathlib.Path,
    method: str,
    theme: str,
    query: int,
    lane: str,
    warmup_iterations: int,
    measurement_iterations: int,
    warmup_seconds: int,
    measurement_seconds: int,
) -> bool:
    if lane not in LANES or not status_path.is_file() or not result_path.is_file():
        return False
    try:
        status = json.loads(status_path.read_text(encoding="utf-8"))
        result = json.loads(result_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return False
    command = status.get("command")
    if status.get("outcome") != "succeeded" or not isinstance(command, list):
        return False
    try:
        command_jar = pathlib.Path(command[command.index("-jar") + 1])
    except (ValueError, IndexError, TypeError):
        return False
    same_jar = command_jar.resolve() == jar.resolve()
    if not same_jar and digest(command_jar) != digest(jar):
        return False
    if not isinstance(result, list) or len(result) != 1 or not isinstance(result[0], dict):
        return False
    benchmark = result[0]
    params = benchmark.get("params")
    primary = benchmark.get("primaryMetric")
    secondary = benchmark.get("secondaryMetrics")
    allocation = (
        secondary.get("gc.alloc.rate.norm") if isinstance(secondary, dict) else None
    )
    raw = primary.get("rawData") if isinstance(primary, dict) else None
    allocation_raw = allocation.get("rawData") if isinstance(allocation, dict) else None
    expected_mode = "ss" if lane == COLD_LANE else "avgt"
    valid = (
        benchmark.get("benchmark") == f"{BENCHMARK_CLASS}.{method}"
        and benchmark.get("mode") == expected_mode
        and benchmark.get("threads") == 1
        and benchmark.get("forks") == 1
        and benchmark.get("warmupIterations") == warmup_iterations
        and benchmark.get("measurementIterations") == measurement_iterations
        and isinstance(params, dict)
        and params.get("themeName") == theme
        and params.get("z_queryIndex") == str(query)
        and isinstance(raw, list)
        and len(raw) == 1
        and isinstance(raw[0], list)
        and len(raw[0]) == measurement_iterations
        and primary.get("scoreUnit") == "ms/op"
        and isinstance(allocation_raw, list)
        and len(allocation_raw) == 1
        and isinstance(allocation_raw[0], list)
        and len(allocation_raw[0]) == measurement_iterations
        and allocation.get("scoreUnit") == "B/op"
    )
    if lane == SATURATED_LANE:
        valid = (
            valid
            and benchmark.get("warmupTime") == f"{warmup_seconds} s"
            and benchmark.get("measurementTime") == f"{measurement_seconds} s"
        )
    return valid


def cell_id(method: str, theme: str, query: int) -> str:
    lane = "uncached" if method == "planUncachedQuery" else "validated-cache"
    return f"{lane}-{theme.lower()}-q{query}"


def run_lane(
    args: argparse.Namespace,
    repo_root: pathlib.Path,
    method: str,
    theme: str,
    query: int,
    lane: str,
) -> None:
    identity = cell_id(method, theme, query)
    lane_identity = f"{identity}.{lane}"
    result_path = args.results / f"{lane_identity}.json"
    status_path = args.results / f"{lane_identity}.status.json"
    stdout_path = args.results / f"{lane_identity}.stdout.log"
    stderr_path = args.results / f"{lane_identity}.stderr.log"
    warmup_iterations = 0 if lane == COLD_LANE else args.warmup_iterations
    measurement_iterations = 1 if lane == COLD_LANE else args.measurements
    if args.resume and completed_lane(
        status_path,
        result_path,
        args.jar,
        method,
        theme,
        query,
        lane,
        warmup_iterations,
        measurement_iterations,
        args.warmup_seconds,
        args.measurement_seconds,
    ):
        print(f"[planning-campaign] retained {lane_identity}", flush=True)
        return
    command = jmh_command(args, method, theme, query, result_path, lane)
    supervisor = [
        sys.executable,
        str((repo_root / "scripts/run-supervised-process.py").resolve()),
        "--timeout-seconds",
        str(args.timeout_seconds),
        "--termination-grace-seconds",
        "5",
        "--status",
        str(status_path.resolve()),
        "--stdout",
        str(stdout_path.resolve()),
        "--stderr",
        str(stderr_path.resolve()),
        "--",
        *command,
    ]
    print(f"[planning-campaign] running {lane_identity}", flush=True)
    result = subprocess.run(supervisor, cwd=repo_root, check=False)
    outcome = "unknown"
    if status_path.is_file():
        outcome = json.loads(status_path.read_text(encoding="utf-8")).get("outcome", "unknown")
    print(f"[planning-campaign] {lane_identity}: {outcome} (exit {result.returncode})", flush=True)


def write_index(args: argparse.Namespace) -> None:
    cells = []
    for status_path in sorted(args.results.glob("*.status.json")):
        status = json.loads(status_path.read_text(encoding="utf-8"))
        identity = status_path.name.removesuffix(".status.json")
        result_path = args.results / f"{identity}.json"
        cells.append(
            {
                "cellId": identity,
                "outcome": status.get("outcome"),
                "elapsedSeconds": status.get("elapsedSeconds"),
                "result": result_path.name if result_path.is_file() else None,
                "resultSha256": digest(result_path),
                "status": status_path.name,
                "statusSha256": digest(status_path),
            }
        )
    index = {
        "formatVersion": 2,
        "jar": str(args.jar.resolve()),
        "jarSha256": digest(args.jar),
        "storeRoot": str(args.store_root.resolve()),
        "coldMeasurements": 1,
        "saturatedMeasurements": args.measurements,
        "saturatedWarmupIterations": args.warmup_iterations,
        "saturatedWarmupSeconds": args.warmup_seconds,
        "saturatedMeasurementSeconds": args.measurement_seconds,
        "externalTimeoutSeconds": args.timeout_seconds,
        "cells": cells,
    }
    (args.results / "campaign-index.json").write_text(
        json.dumps(index, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )


def main() -> int:
    args = parse_args()
    repo_root = pathlib.Path(__file__).resolve().parents[1]
    args.results.mkdir(parents=True, exist_ok=True)
    themes = tuple(args.theme or THEMES)
    queries = tuple(args.query or range(13))
    methods = tuple(args.method or METHODS)
    lanes = tuple(args.lane or LANES)
    cells = [
        (method, theme, query, lane)
        for method in methods
        for theme in themes
        for query in queries
        for lane in lanes
    ]
    if args.max_cells is not None:
        cells = cells[: args.max_cells]
    for method, theme, query, lane in cells:
        run_lane(args, repo_root, method, theme, query, lane)
        write_index(args)
    write_index(args)
    return 0


if __name__ == "__main__":
    sys.exit(main())
